"""Saga compensations generated by inversion, and what happens under
concurrency.

A saga runs a business transaction as local steps (reserve stock, charge the
customer, award loyalty points, book shipping). When a later step fails, the
completed steps are undone by *compensating* actions, which today are written
by hand. Here each step is a small Reverie program, and its compensation is
the same program run backward, so it is correct by construction against the
state the step produced.

Real sagas are not isolated: other transactions touch the same balances
between a step and its compensation. Two properties decide what happens then:

* Reverie steps are *updates* (``x += e``, ``x -= e``), not overwrites. An
  inverted update subtracts what the step added, so it commutes with
  concurrent updates to the same balance. Restoring a saved "before" value
  does not: it silently erases everything that happened in between.
* Where a step destroys information (here a loyalty-point cap), it must keep
  a witness, and the inverse re-checks the step's branch conditions. If
  concurrent activity has made exact undo impossible, the compensation
  *fails loudly* (an assertion) instead of silently writing a wrong value.

:func:`run_trial` plays one saga with concurrent traffic and compensates it
three ways (Reverie inverse, snapshot restore, a typical hand-written
compensation), each compared with the ideal outcome: the concurrent traffic
applied as if the saga had never run.
"""

from __future__ import annotations

import random
from dataclasses import dataclass
from typing import Any, Callable, Dict, List, Optional, Tuple

from ._reverie import Program, loads
from ._types import ExecutionError

__all__ = ["STEPS", "LOSSY_LOYALTY_SOURCE", "run_trial", "Outcome"]

FEE_PER_MILLE = 29
FEE_FIXED = 30
POINTS_CAP = 1_000

#: Each saga step as Reverie source. Inputs (`item`, `qty`, `amount`,
#: `earned`) are part of the saga record; witnesses live in the store.
STEPS: Dict[str, str] = {
    "reserve": """\
global stock: tensor<int, 4>;
global reserved: tensor<int, 4>;
global item = 0;
global qty = 0;

procedure main() {
  stock[item] -= qty;
  reserved[item] += qty;
  assert stock[item] >= 0
}
""",
    "charge": f"""\
global wallet = 0;
global merchant = 0;
global fees = 0;
global amount = 0;

procedure main() {{
  wallet -= amount;
  merchant += amount - (amount * {FEE_PER_MILLE} / 1000 + {FEE_FIXED});
  fees += amount * {FEE_PER_MILLE} / 1000 + {FEE_FIXED};
  assert wallet >= 0
}}
""",
    "loyalty": f"""\
global points = 0;
global earned = 0;
global overflow: witness<int>;

procedure main() {{
  points += earned;
  if points > {POINTS_CAP} then
    overflow += points - {POINTS_CAP};
    points -= overflow
  fi overflow > 0
}}
""",
    # The same step written "decide on recorded inputs, apply as a delta":
    # the cap decision uses `seen` (the balance it saw), and the balance
    # only receives `applied`. Its inverse subtracts exactly `applied`, so it
    # commutes with concurrent changes; whatever drift happened in between
    # is left in `seen` as an audit trail.
    "loyalty_delta": f"""\
global points = 0;
global earned = 0;
global seen: witness<int>;
global applied: witness<int>;
global clipped: witness<int>;

procedure main() {{
  seen += points;
  applied += earned;
  if applied > {POINTS_CAP} - seen then
    clipped += applied - ({POINTS_CAP} - seen);
    applied -= clipped
  fi clipped > 0;
  points += applied
}}
""",
    "ship": """\
global quota = 0;
global shipments = 0;

procedure main() {
  quota -= 1;
  shipments += 1;
  assert quota >= 0
}
""",
}

#: The obvious way to write the loyalty step. Reverie rejects it: the clamp
#: reads the value it overwrites, which destroys the pre-cap total.
LOSSY_LOYALTY_SOURCE = f"""\
global points = 0;
global earned = 0;

procedure main() {{
  points += earned;
  if points > {POINTS_CAP} then
    points -= points - {POINTS_CAP}
  fi points == {POINTS_CAP}
}}
"""

ORDER = ("reserve", "charge", "loyalty", "ship")
WORLD = ("stock", "reserved", "wallet", "merchant", "fees", "points", "quota", "shipments")


def _programs() -> Dict[str, Program]:
    return {name: loads(source) for name, source in STEPS.items()}


def _hand_written(step: str, world: Dict[str, Any], args: Dict[str, int]) -> None:
    """Compensations as commonly hand-written: plausible, and subtly wrong
    for the capped loyalty step (it removes the full award even when the cap
    absorbed part of it)."""
    if step == "reserve":
        world["stock"][args["item"]] += args["qty"]
        world["reserved"][args["item"]] -= args["qty"]
    elif step == "charge":
        fee = args["amount"] * FEE_PER_MILLE // 1000 + FEE_FIXED
        world["wallet"] += args["amount"]
        world["merchant"] -= args["amount"] - fee
        world["fees"] -= fee
    elif step.startswith("loyalty"):
        world["points"] -= args["earned"]
    elif step == "ship":
        world["quota"] += 1
        world["shipments"] -= 1


def _concurrent_op(rng: random.Random) -> Callable[[Dict[str, Any]], None]:
    """Another transaction touching the same records (plain application code)."""
    kind = rng.choice(("deposit", "sale", "restock", "earn", "spend", "none"))
    item = rng.randrange(4)
    value = rng.randrange(1, 400)

    def apply(world: Dict[str, Any]) -> None:
        if kind == "deposit":
            world["wallet"] += value
        elif kind == "sale":
            take = min(world["stock"][item], value // 40)
            world["stock"][item] -= take
        elif kind == "restock":
            world["stock"][item] += value // 20
        elif kind == "earn":
            world["points"] = min(world["points"] + value, POINTS_CAP)
        elif kind == "spend":
            world["points"] -= min(world["points"], value)

    return apply


@dataclass
class Outcome:
    """How one compensation strategy did against the ideal outcome."""

    correct: int = 0
    loud_failure: int = 0
    silent_corruption: int = 0


def _copy(world: Dict[str, Any]) -> Dict[str, Any]:
    return {k: (list(v) if isinstance(v, list) else v) for k, v in world.items()}


def run_trial(
    rng: random.Random,
    programs: Optional[Dict[str, Program]] = None,
    *,
    loyalty: str = "loyalty",
) -> Dict[str, str]:
    """One saga with concurrent traffic. Returns, per strategy, "correct",
    "loud_failure" or "silent_corruption" (or "no_compensation" when the
    saga succeeds). ``loyalty`` picks the loyalty step's style: "loyalty"
    (re-derives the cap from the current balance) or "loyalty_delta"."""
    programs = programs or _programs()
    order = tuple(loyalty if step == "loyalty" else step for step in ORDER)
    world0 = {
        "stock": [rng.randrange(0, 30) for _ in range(4)],
        "reserved": [0] * 4,
        "wallet": rng.randrange(0, 20_000),
        "merchant": 0,
        "fees": 0,
        "points": rng.randrange(600, POINTS_CAP + 1),
        "quota": rng.randrange(0, 3),
        "shipments": 0,
    }
    args = {
        "item": rng.randrange(4),
        "qty": rng.randrange(1, 6),
        "amount": rng.randrange(500, 15_000),
        "earned": rng.randrange(10, 300),
    }
    # Concurrent transactions interleave between the saga's steps and its
    # compensation; we record them to compute the ideal outcome.
    concurrent: List[Callable[[Dict[str, Any]], None]] = []
    deltas: List[Dict[str, Any]] = []  # what each concurrent op actually changed
    world = _copy(world0)

    def apply_concurrent(op) -> None:
        before = _copy(world)
        op(world)
        concurrent.append(op)
        deltas.append(
            {
                k: (
                    [a - b for a, b in zip(world[k], before[k])]
                    if isinstance(world[k], list)
                    else world[k] - before[k]
                )
                for k in WORLD
            }
        )
    snapshots: List[Tuple[str, Dict[str, Any]]] = []
    done: List[Tuple[str, Dict[str, Any]]] = []
    failed = False
    for step in order:
        for _ in range(rng.randrange(0, 3)):
            apply_concurrent(_concurrent_op(rng))
        before = _copy(world)
        store = {k: world[k] for k in WORLD if k in STEPS[step]}
        store.update({k: v for k, v in args.items() if f"global {k} " in STEPS[step]})
        try:
            after = programs[step].run(store)
        except ExecutionError:
            failed = True
            break
        snapshots.append((step, before))
        done.append((step, {k: after[k] for k in after if k not in WORLD}))
        for k in WORLD:
            if k in after:
                world[k] = after[k]
    if not failed:
        return {
            "reverie": "no_compensation",
            "snapshot": "no_compensation",
            "hand": "no_compensation",
            "dirty_read": "n/a",
        }
    for _ in range(rng.randrange(0, 4)):
        apply_concurrent(_concurrent_op(rng))

    # Two notions of the right answer:
    # - "committed": keep what other transactions actually changed, remove
    #   only the saga's effect (what a compensation can be asked to do);
    # - "serial": as if the saga had never run. Differs when a concurrent
    #   transaction *read* the saga's effects (a dirty read), which no
    #   compensation can undo.
    committed = _copy(world0)
    for delta in deltas:
        for k, d in delta.items():
            if isinstance(d, list):
                committed[k] = [a + b for a, b in zip(committed[k], d)]
            else:
                committed[k] += d
    serial = _copy(world0)
    for op in concurrent:
        op(serial)
    dirty = any(committed[k] != serial[k] for k in WORLD)

    def judge(result: Optional[Dict[str, Any]]) -> str:
        if result is None:
            return "loud_failure"
        return "correct" if all(result[k] == committed[k] for k in WORLD) else "silent_corruption"

    # 1. Reverie: run each completed step backward, newest first.
    rev: Optional[Dict[str, Any]] = _copy(world)
    try:
        for step, extra in reversed(done):
            store = {k: rev[k] for k in WORLD if k in STEPS[step]}
            store.update(extra)
            back = programs[step].reverse(store)
            for k in WORLD:
                if k in back:
                    rev[k] = back[k]
    except ExecutionError:
        rev = None

    # 2. Snapshot restore: put back each touched record's "before" value.
    snap = _copy(world)
    for step, before in reversed(snapshots):
        for k in WORLD:
            if k in STEPS[step]:
                snap[k] = before[k] if not isinstance(before[k], list) else list(before[k])

    # 3. Hand-written compensations.
    hand = _copy(world)
    for step, _ in reversed(done):
        _hand_written(step, hand, args)

    return {
        "reverie": judge(rev),
        "snapshot": judge(snap),
        "hand": judge(hand),
        "dirty_read": "yes" if dirty else "no",
    }
